public class Main {
    static int length(Object obj) {
        if (obj instanceof String s && s.length() > 2) {
            return s.length();
        }
        return -1;
    }
    public static void main(String[] args) {
        System.out.print(length("Java") + ":");
        System.out.print(length("A") + ":");
        System.out.print(length(10));
    }
}

