        System.out.print(ok("A"));
    }
}

public class Main {
    static void print(Object obj) {
        if (!(obj instanceof String s)) {
            System.out.print("N");
            return;
        }

        System.out.print(s.toUpperCase());
    }

    public static void main(String[] args) {
        print("java");
        System.out.print(":");
        print(10);
    }
}

